"use client";

import { useCallback, useMemo, useState } from "react";
import CodeMirror from "@uiw/react-codemirror";
import { javascript } from "@codemirror/lang-javascript";
import { css } from "@codemirror/lang-css";
import { json } from "@codemirror/lang-json";
import { Braces, Check, Copy } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ScrollArea, ScrollBar } from "@/components/ui/scroll-area";
import { cn } from "@/lib/utils";
import { sandboxCodeMirrorTheme } from "@/lib/sandbox/codemirror-theme";
import type { SandboxFile } from "@/lib/sandbox/types";
import {
  getLanguageBadge,
  getLanguageLabel,
  sandboxPanelClassName,
} from "@/lib/sandbox/utils";

interface CodeEditorProps {
  files: SandboxFile[];
  activeFileId: string;
  onActiveFileChange: (id: string) => void;
  onChange: (id: string, content: string) => void;
  onFormat?: () => void;
  readOnly?: boolean;
  className?: string;
}

export function CodeEditor({
  files,
  activeFileId,
  onActiveFileChange,
  onChange,
  onFormat,
  readOnly = false,
  className,
}: CodeEditorProps) {
  const [copied, setCopied] = useState(false);
  const activeFile = files.find((file) => file.id === activeFileId) ?? files[0];

  const extensions = useMemo(() => {
    if (!activeFile) return sandboxCodeMirrorTheme;
    let languageExt;
    switch (activeFile.language) {
      case "tsx":
      case "ts":
        languageExt = javascript({ jsx: true, typescript: true });
        break;
      case "css":
        languageExt = css();
        break;
      case "json":
        languageExt = json();
        break;
      default:
        languageExt = javascript({ jsx: true, typescript: true });
    }
    return [...sandboxCodeMirrorTheme, languageExt];
  }, [activeFile]);

  const handleCopy = useCallback(async () => {
    if (!activeFile) return;
    await navigator.clipboard.writeText(activeFile.content);
    setCopied(true);
    window.setTimeout(() => setCopied(false), 1500);
  }, [activeFile]);

  if (!activeFile) {
    return null;
  }

  return (
    <div className={sandboxPanelClassName(className)}>
      <div className="flex items-center justify-between gap-3 border-b border-white/[0.06] bg-[#101012] px-2 py-1.5">
        <ScrollArea className="max-w-full flex-1 whitespace-nowrap">
          <div className="flex items-end">
            {files.map((file) => {
              const isActive = file.id === activeFileId;
              return (
                <button
                  key={file.id}
                  type="button"
                  onClick={() => onActiveFileChange(file.id)}
                  className={cn(
                    "relative inline-flex items-center gap-1.5 border-r border-white/[0.06] px-3 py-2 text-[11px] transition-colors",
                    isActive
                      ? "bg-sandbox-editor-bg text-foreground"
                      : "text-muted-foreground hover:bg-white/[0.03] hover:text-foreground"
                  )}
                >
                  {isActive ? (
                    <span className="absolute inset-x-0 top-0 h-px bg-white/30" />
                  ) : null}
                  <span className="font-mono">{file.name}</span>
                  {file.isDirty ? (
                    <span className="size-1.5 rounded-full bg-amber-400" />
                  ) : null}
                </button>
              );
            })}
          </div>
          <ScrollBar orientation="horizontal" />
        </ScrollArea>
        <div className="flex shrink-0 items-center gap-1.5">
          <Badge
            variant="outline"
            className="border-white/10 bg-white/[0.03] font-mono text-[10px] text-muted-foreground"
          >
            {getLanguageBadge(activeFile.language)}
          </Badge>
          {onFormat ? (
            <Button
              variant="ghost"
              size="xs"
              className="text-muted-foreground hover:text-foreground"
              onClick={onFormat}
            >
              <Braces />
              Format
            </Button>
          ) : null}
          <Button
            variant="ghost"
            size="xs"
            className="text-muted-foreground hover:text-foreground"
            onClick={handleCopy}
          >
            {copied ? <Check /> : <Copy />}
            {copied ? "Copied" : "Copy"}
          </Button>
        </div>
      </div>
      <div className="flex items-center justify-between border-b border-white/[0.06] bg-sandbox-editor-bg/80 px-3 py-1">
        <p className="truncate font-mono text-[10px] text-zinc-500">
          {activeFile.path}
        </p>
        <p className="shrink-0 text-[10px] text-zinc-600">
          {getLanguageLabel(activeFile.language)}
        </p>
      </div>
      <div className="sandbox-codemirror bg-sandbox-editor-bg [&_.cm-editor]:min-h-[320px] [&_.cm-editor]:bg-transparent [&_.cm-editor]:outline-none [&_.cm-scroller]:text-[13px] [&_.cm-scroller]:leading-6">
        <CodeMirror
          value={activeFile.content}
          height="100%"
          minHeight="320px"
          theme="none"
          extensions={extensions}
          editable={!readOnly}
          onChange={(value) => onChange(activeFile.id, value)}
          basicSetup={{
            lineNumbers: true,
            foldGutter: true,
            highlightActiveLine: true,
            highlightActiveLineGutter: true,
            bracketMatching: true,
            indentOnInput: true,
            closeBrackets: true,
          }}
        />
      </div>
    </div>
  );
}

import { HighlightStyle, syntaxHighlighting } from "@codemirror/language";
import { EditorView } from "@codemirror/view";
import { tags as t } from "@lezer/highlight";

const editorTheme = EditorView.theme(
  {
    "&": {
      color: "#d4d4d8",
      backgroundColor: "transparent",
    },
    ".cm-scroller": {
      overflow: "auto",
      fontFamily:
        '"Geist Mono", "Geist Mono Fallback", ui-monospace, SFMono-Regular, monospace',
    },
    ".cm-content": {
      caretColor: "#fafafa",
      padding: "12px 0",
    },
    ".cm-line": {
      padding: "0 12px 0 4px",
    },
    ".cm-gutters": {
      backgroundColor: "rgba(255,255,255,0.02)",
      color: "#52525b",
      border: "none",
      borderRight: "1px solid rgba(255,255,255,0.06)",
      paddingRight: "4px",
    },
    ".cm-gutterElement": {
      padding: "0 10px 0 8px",
      minWidth: "2.75rem",
    },
    ".cm-activeLineGutter": {
      backgroundColor: "rgba(255,255,255,0.04)",
      color: "#a1a1aa",
    },
    ".cm-activeLine": {
      backgroundColor: "rgba(255,255,255,0.03)",
    },
    ".cm-selectionBackground, &.cm-focused .cm-selectionBackground": {
      backgroundColor: "rgba(255,255,255,0.1) !important",
    },
    "&.cm-focused": {
      outline: "none",
    },
    ".cm-cursor, .cm-dropCursor": {
      borderLeftColor: "#fafafa",
      borderLeftWidth: "2px",
    },
    ".cm-foldPlaceholder": {
      backgroundColor: "rgba(255,255,255,0.06)",
      border: "none",
      color: "#71717a",
    },
    ".cm-matchingBracket, .cm-nonmatchingBracket": {
      backgroundColor: "rgba(255,255,255,0.08)",
      outline: "1px solid rgba(255,255,255,0.12)",
    },
  },
  { dark: true }
);

const highlightStyle = HighlightStyle.define([
  { tag: t.keyword, color: "#c4b5fd" },
  { tag: [t.name, t.deleted, t.character, t.macroName], color: "#e4e4e7" },
  { tag: [t.propertyName], color: "#93c5fd" },
  {
    tag: [t.function(t.variableName), t.labelName],
    color: "#fcd34d",
  },
  { tag: [t.color, t.constant(t.name), t.standard(t.name)], color: "#fca5a5" },
  { tag: [t.definition(t.name), t.separator], color: "#e4e4e7" },
  {
    tag: [
      t.typeName,
      t.className,
      t.number,
      t.changed,
      t.annotation,
      t.modifier,
      t.self,
      t.namespace,
    ],
    color: "#67e8f9",
  },
  {
    tag: [
      t.operator,
      t.operatorKeyword,
      t.url,
      t.escape,
      t.regexp,
      t.link,
      t.special(t.string),
    ],
    color: "#a1a1aa",
  },
  { tag: [t.meta, t.comment], color: "#52525b", fontStyle: "italic" },
  { tag: t.strong, fontWeight: "bold", color: "#fafafa" },
  { tag: t.emphasis, fontStyle: "italic" },
  { tag: t.strikethrough, textDecoration: "line-through" },
  { tag: t.link, color: "#93c5fd", textDecoration: "underline" },
  { tag: t.heading, fontWeight: "bold", color: "#fafafa" },
  { tag: [t.atom, t.bool, t.special(t.variableName)], color: "#fca5a5" },
  { tag: [t.processingInstruction, t.string, t.inserted], color: "#86efac" },
  { tag: t.invalid, color: "#fca5a5", borderBottom: "1px dotted #ef4444" },
]);

export const sandboxCodeMirrorTheme = [
  editorTheme,
  syntaxHighlighting(highlightStyle),
];

export type ViewportSize = "desktop" | "tablet" | "mobile";
export type ConsoleLevel = "log" | "info" | "warn" | "error";
export type PreviewStatus = "idle" | "loading" | "ready" | "error";

export interface SandboxFile {
  id: string;
  name: string;
  path: string;
  language: "tsx" | "ts" | "css" | "json";
  content: string;
  isDirty?: boolean;
}

export interface ConsoleMessage {
  id: string;
  level: ConsoleLevel;
  message: string;
  timestamp: Date;
  source?: string;
}

export interface PackageInstallEvent {
  id: string;
  name: string;
  version: string;
  status: "pending" | "success" | "error";
  output?: string;
}

export interface RuntimeError {
  title: string;
  message: string;
  stack: string;
  file: string;
  line: number;
  column?: number;
}

export interface FileTreeNode {
  id: string;
  name: string;
  type: "file" | "folder";
  children?: FileTreeNode[];
  fileId?: string;
}

export interface SandboxState {
  files: SandboxFile[];
  originalContents: Record<string, string>;
  activeFileId: string;
  fileTree: FileTreeNode[];
  consoleMessages: ConsoleMessage[];
  installEvents: PackageInstallEvent[];
  runtimeError: RuntimeError | null;
  previewStatus: PreviewStatus;
  viewport: ViewportSize;
  previewSrcDoc: string;
  consoleCollapsed: boolean;
}

import type { FileTreeNode, SandboxFile } from "./types";

export function getLanguageLabel(language: SandboxFile["language"]): string {
  const labels: Record<SandboxFile["language"], string> = {
    tsx: "TypeScript React",
    ts: "TypeScript",
    css: "CSS",
    json: "JSON",
  };
  return labels[language];
}

export function getLanguageBadge(language: SandboxFile["language"]): string {
  const badges: Record<SandboxFile["language"], string> = {
    tsx: "TSX",
    ts: "TS",
    css: "CSS",
    json: "JSON",
  };
  return badges[language];
}

export function formatTimestamp(date: Date): string {
  return date.toLocaleTimeString("en-US", {
    hour12: false,
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
}

export function formatCode(content: string): string {
  const lines = content.split("\n");
  let indent = 0;
  const formatted: string[] = [];

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) {
      formatted.push("");
      continue;
    }

    if (/^[\}\]\)]/.test(trimmed)) {
      indent = Math.max(0, indent - 1);
    }

    formatted.push(`${"  ".repeat(indent)}${trimmed}`);

    const openBrackets = (trimmed.match(/[\{\[\(]/g) || []).length;
    const closeBrackets = (trimmed.match(/[\}\]\)]/g) || []).length;
    indent += openBrackets - closeBrackets;
    indent = Math.max(0, indent);
  }

  return formatted.join("\n");
}

export function findFileIdInTree(
  nodes: FileTreeNode[],
  fileId: string
): string | null {
  for (const node of nodes) {
    if (node.type === "file" && node.fileId === fileId) {
      return node.id;
    }
    if (node.children) {
      const found = findFileIdInTree(node.children, fileId);
      if (found) return found;
    }
  }
  return null;
}

export function removeFileFromTree(
  nodes: FileTreeNode[],
  fileId: string
): FileTreeNode[] {
  return nodes
    .filter((node) => !(node.type === "file" && node.fileId === fileId))
    .map((node) =>
      node.children
        ? { ...node, children: removeFileFromTree(node.children, fileId) }
        : node
    );
}

export function addFileToTree(
  nodes: FileTreeNode[],
  file: SandboxFile
): FileTreeNode[] {
  const parts = file.path.split("/");
  if (parts.length === 1) {
    return [
      ...nodes,
      {
        id: `tree-${file.id}`,
        name: file.name,
        type: "file" as const,
        fileId: file.id,
      },
    ];
  }

  const [folderName, ...rest] = parts;
  const folderId = `folder-${folderName}`;
  const existingFolderIndex = nodes.findIndex(
    (node) => node.type === "folder" && node.name === folderName
  );

  if (existingFolderIndex >= 0) {
    const folder = nodes[existingFolderIndex];
    const updatedFolder: FileTreeNode = {
      ...folder,
      children: addFileToTree(folder.children ?? [], {
        ...file,
        path: rest.join("/"),
      }),
    };
    return nodes.map((node, index) =>
      index === existingFolderIndex ? updatedFolder : node
    );
  }

  return [
    ...nodes,
    {
      id: folderId,
      name: folderName,
      type: "folder" as const,
      children: addFileToTree([], { ...file, path: rest.join("/") }),
    },
  ];
}

export function sandboxPanelClassName(className?: string): string {
  return [
    "overflow-hidden rounded-xl border border-white/[0.06] bg-[#101012]/90",
    className,
  ]
    .filter(Boolean)
    .join(" ");
}

export function getViewportWidth(viewport: "desktop" | "tablet" | "mobile") {
  const widths = {
    desktop: "100%",
    tablet: "768px",
    mobile: "390px",
  } as const;
  return widths[viewport];
}

export function formatRuntimeErrorForCopy(error: {
  title: string;
  message: string;
  stack: string;
  file: string;
  line: number;
  column?: number;
}): string {
  return `${error.title}: ${error.message}
at ${error.file}:${error.line}${error.column ? `:${error.column}` : ""}

${error.stack}`;
}
